---Refresh 
---@param data CardDojo  @ 卡牌数据
---@param cardCb fun():void @ 点击卡头像回调
---@param bgCb fun():void @ 点击添加区域回调
---@param isLockHelper boolean 是否是锁定的机器人
function UIFightTeamTeamNode:Refresh(data, cardCb, bgCb, memberPos, levelId, bufferTeam,teamIndex)
    self._memberPos = checkNumber(memberPos)

    self._data = data
    self._cardCb = cardCb
    self._bgCb = bgCb
    self._curLevelId = checkNumber(levelId)             
    self._bufferTeam = checkTable(bufferTeam)

    if not isNull(teamIndex) then
        self._teamIndex = teamIndex
    end


    CfUtils.SetActive(self.Mask, false)
    --如果有数据
    if self._data then
        KTool.SetActive(self.CommonHeadItemNode, true)
        if self._cardHeadNodeScr then
            self._cardHeadNodeScr:FreshNode(self._data, true)
            self._cardHeadNodeScr:SetCallBack(function()
                if self._cardCb then
                    self._cardCb()
                end
            end)
        end
        KTool.SetActive(self.Image, false)

        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curLevelId)
        if vo then
            --有上阵条件
            if checkNumber(vo.roleRestrictions) > 0 then
                local isLimit = QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Limit, self._data.cardId)
                local isLimitCard = GameUtils.IsLimitCard(self._curLevelId,self._data.id,self._teamIndex)
                if isLimit or isLimitCard then
                    CfUtils.SetActive(self.Mask, true)
                    CfUtils.SetActive(self.CaseBg, true)
                    CfUtils.SetActive(self.ImgBlack, true)
                    CfUtils.SetUISwitchImage(self.CaseBg, 3)
                    CfUtils.SetUISwitchText(self.CaseText, 3)
                end
                local isMust = QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Must, self._data.cardId)
                if isMust then
                    CfUtils.SetActive(self.Mask, true)
                    CfUtils.SetActive(self.CaseBg, true)
                    CfUtils.SetActive(self.ImgGlow, true)
                    CfUtils.SetActive(self.ImgBlack, false)
                    CfUtils.SetUISwitchImage(self.CaseBg, 2)
                    CfUtils.SetUISwitchText(self.CaseText, 2)
                end
            else ---没上阵条件时  如果是社团Boss 也要加限制 一张卡一天只能用一次
                local isLimitCard = GameUtils.IsLimitCard(self._curLevelId,self._data.id,self._teamIndex)
                if isLimitCard then
                    CfUtils.SetActive(self.Mask, true)
                    CfUtils.SetActive(self.CaseBg, true)
                    CfUtils.SetActive(self.ImgBlack, true)
                    CfUtils.SetUISwitchImage(self.CaseBg, 3)
                    CfUtils.SetUISwitchText(self.CaseText, 3)
                end
            end 
        end

    else
        KTool.SetActive(self.CommonHeadItemNode, false)
        KTool.SetActive(self.HpEnergy, false)
        KTool.SetActive(self.IconPowerPoint, false)
        KTool.SetActive(self.Image, true)
    end
end

--羁绊信息
---@param tmDojo TeamMemberDojo
---@param cb fun():void
---@param isDontShowAni integer
function UIFightTeamTeamNode:FillFettersInfo(tmDojo, cb, isDontShowAni)
    if self._isLimit then
        return
    end

    local curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)
    if curLevelType == Constants.IDType.Fairyland then
        CfUtils.SetActive(self.FetterItem, false)
        -- CfUtils.SetActive(self.FetterItem.transform:Find("StatusLock"), true)
        return
    end

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id20001)
    SetButtonAction(self.FetterItem, function()
        if not isUnlock then
            GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id20001))
            return
        end
        if cb then
            cb()
        end
    end)

    CfUtils.SetActive(self.ImgAdd, isUnlock)
    CfUtils.SetActive(self.FetterItem.transform:Find("StatusLock"), not isUnlock)
    if not isUnlock then
        return
    end

    self._tmDojo = tmDojo 
    if not self._tmDojo then
        return
    end      

    local isHasFetters = checkNumber(self._tmDojo.fettersId) > 0
    CfUtils.SetActive(self.HeadGroup, isHasFetters)
    
    if checkNumber(isDontShowAni) == 0 then
        CfUtils.PlayAnimation(self.controller.gameObject.transform:Find("AnimRoot"), "FightTeamDialogTeamNode_Swtich")
    else
        CfUtils.PlayAnimation(self.controller.gameObject.transform:Find("AnimRoot"), "FightTeamDialogTeamNode_Default")
    end
    if isHasFetters then
        local cardVo
        if checkNumber(self._tmDojo.type) == Constants.TeamMemberType.QuestLockHelperCard then
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(tmDojo.fettersId)
        elseif checkNumber(self._tmDojo.type) == Constants.TeamMemberType.HelperCard then
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(tmDojo.fettersCardId)
        else
            local dojo = cardComponent:GetCardById(self._tmDojo.fettersId)
            cardVo = CardConfMgr:GetInstance():GetCardByRefId(dojo.cardId)

            local rare = cardVo.rare
            local advanceLevel = dojo and checkNumber(dojo.advanceLevel) or 0
            if advanceLevel > 0 then
                rare = CardConfMgr:GetInstance():GetCardRare(advanceLevel, rare)
            end

            CfUtils.SetUISwitchImage(self.ImgQuality, rare)
        end

        if cardVo then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
            if skinVo then
                CfUtils.FillImage(self.ImgCardHead, skinVo.buffHead)

                local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(self._tmDojo.cardId, cardVo.roleId)
                local isActiveFetters = fettersId > 0
                CfUtils.SetActive(self.ImgIconFetter, isActiveFetters)
                CfUtils.SetActive(self.HeadGroup.transform:Find("UIFX_FightTeamDialogFetterItem"), isActiveFetters)
            end
        end
    end

    if checkNumber(tmDojo.type) == Constants.TeamMemberType.QuestLockHelperCard then
        CfUtils.SetActive(self.ImgAdd, false)
        CfUtils.SetActive(self.FetterItem.transform:Find("StatusLock"), true)
    end

    SetButtonAction(self.FetterItem, function()
        if cb then
            cb()
        end
    end)
end 

