--是否是up角色
function UIFightTeamTeamNode:FillUpBuffInfo(upBuffData)
    if not upBuffData or not self._data then
        KTool.SetActive(self.UPbuff, false)
        CfUtils.SetActive(self.UpRoleAddition, false)
        return
    end
    local isUp, buffData = QuestConfMgr:GetInstance():IsCardUp(self._data.cardId, upBuffData)
    KTool.SetActive(self.UPbuff, isUp)
    self:FillUpRoleAddition(isUp, buffData)
end

---@param allTeamPosInfo table[] @ 整个队伍信息，用于拖拽交换位置后更新索引
---@param cb fun():void @ 交换位置成功后的回调
---@param levelId integer @ 关卡id（用于通过 teamComponent 获取编队数据，进行更新）
---@param teamIndex integer @ 编队位置
function UIFightTeamTeamNode:InitChangePosInfo(allTeamPosInfo, cb, levelId, teamIndex)
    self._teamIndex = checkNumber(teamIndex)
    self._curLevelId = checkNumber(levelId)             
    self._refreshPosCb = cb
    self._allTeamPosInfo = checkTable(allTeamPosInfo)
    self:InitDrag()
end

function UIFightTeamTeamNode:InitDrag()
    local drag = EventDragProxy.Create(self.CommonHeadItemNode.gameObject)
    drag.onPointerBeginDrag = Bind(self, self.OnBeginDrag)
    drag.onPointerDrag = Bind(self, self.OnDrag)
    drag.onPointerEndDrag = Bind(self, self.OnEndDrag)
end

function UIFightTeamTeamNode:OnBeginDrag(eventData)
    if isNull(eventData) then return end

    local hl = self.controller.gameObject.transform.parent:GetComponent(HorizontalLayoutGroup)
    if not isNull(hl) then
        hl.enabled = false
    end
    self._curSiblingInd = self.controller.gameObject.transform:GetSiblingIndex()
    self.controller.gameObject.transform:SetSiblingIndex(4)
end

---@param eventData UnityEngine.EventSystems.PointerEventData
function UIFightTeamTeamNode:OnDrag(eventData)
    if eventData.clickCount > 1 then
        return
    end
    if isNull(eventData) then return end
    local pos = eventData.delta

    local uiCamera = CS.Game.Native.URP.URPCameraController.Instance.uiCamera
    local topLayerRt = self.controller.gameObject.transform.parent.transform:GetComponent("RectTransform")
    local bool, vecNow = RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, eventData.position, uiCamera)
    self:RefreshPos(Vector3(vecNow.x, vecNow.y, 0))
end

function UIFightTeamTeamNode:OnEndDrag(eventData)
    local hl = self.controller.gameObject.transform.parent:GetComponent(HorizontalLayoutGroup)
    if not isNull(hl) then
        hl.enabled = true
    end
    self.controller.gameObject.transform:SetSiblingIndex(self._curSiblingInd)

    if isNull(eventData) or isNull(self._allTeamPosInfo) then return end
    for k, v in pairs(self._allTeamPosInfo) do
        --解锁才交换
        if v.memberPos ~= self._memberPos and not v.isLimitPos then
            local rect = v.go.transform:GetComponent(typeof(RectTransform))
            local pos = self.controller.transform.position
            local isChange = RectTransformUtility.RectangleContainsScreenPoint(rect, Vector2(pos.x, pos.y))
            if isChange then
                self.curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)     --关卡类型
                if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                    local t = self._bufferTeam
                    local data = t[v.memberPos]
                    t[v.memberPos] = t[self._memberPos]
                    t[self._memberPos] = data

                    local t1 = {
                        {}
                    }
                    local cardsInfo = teamComponent:GetAllCardId(t, true)
                    local maxNum = regionQuestMgr:GetOwnTeamNum()
                    if #cardsInfo > maxNum then
                        for i =  #cardsInfo, maxNum + 1, -1 do
                            table.remove(cardsInfo, i)
                        end
                    end
                    t1[1].cardsInfo = cardsInfo
                    t1[1].mergeSkill = 0
                    
                    local cardIds = table.serialize(t1)
                    regionQuestMgr:TeamReq({roomSet = cardIds})
                else
                    local teamTab = teamComponent:GetTeamByQuestId(self._curLevelId, self._teamIndex)
                    local data = teamTab[v.memberPos]
                    teamTab[v.memberPos] = teamTab[self._memberPos]
                    teamTab[self._memberPos] = data
                    self:RefreshPos(self._autoPos)

                    teamComponent:SetTeamByQuestId(self._curLevelId, teamTab, 0, self._teamIndex, nil, nil, 1)
                end

                if self._refreshPosCb then
                    self._refreshPosCb()
                end
                return
            end
        end
    end

    self:RefreshPos(self._autoPos)
end

--刷新位置
function UIFightTeamTeamNode:RefreshPos(pos)
    if not pos then
        return nil
    end
    self.controller.gameObject.transform.localPosition = pos
end

function UIFightTeamTeamNode:OnBtnBg()
    if self._bgCb then
        self._bgCb()
    end
end

function UIFightTeamTeamNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

