---卡牌up提升
function UIFightTeamTeamNode:FillUpRoleAddition(isUp, buffData)
    if isUp then
        CfUtils.SetActive(self.UpRoleAddition, true)
        local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(buffData.commonAddId)
        if vo then
            CfUtils.FillText(self.UpRoleAdditionTextDesc, vo.desc)
        end
    else
        CfUtils.SetActive(self.UpRoleAddition, false)
    end
end

